.bible-footer a:hover {
  text-decoration: underline;
}

/* ==========================================================================
   Comprehensive Responsive Design System: Phones, Tablets & Laptops
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. Touch Devices (No Mouse Hover)
   -------------------------------------------------------------------------- */
@media (hover: none) {
  .verse-actions-bar {
    display: inline-flex !important;
    opacity: 0.75;
  }
  .btn-verse-bookmark,
  .btn-verse-copy {
    width: 32px;
    height: 32px;
    font-size: 0.85rem;
  }
  .verse-item:active .verse-actions-bar {
    opacity: 1;
  }
}

/* --------------------------------------------------------------------------
   2. Tablets & Small Laptops (max-width: 1024px)
   -------------------------------------------------------------------------- */
@media (max-width: 1024px) {
  .header-inner {
    padding: 0.75rem 1rem;
  }
  .bible-main {
    padding: 1.25rem 1rem;
    gap: 1.25rem;
  }
  .reader-card {
    padding: 2rem 1.75rem;
  }
  .passage-nav-bar {
    gap: 0.75rem;
  }
  .daily-verse-card {
    padding: 1.75rem 1.5rem;
  }
  .bookmarks-grid {
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  }
}

/* --------------------------------------------------------------------------
   3. Mobile Phones & Portrait Tablets (max-width: 768px)
   -------------------------------------------------------------------------- */
@media (max-width: 768px) {
  /* Header Layout */
  .header-inner {
    flex-direction: column;
    align-items: stretch;
    gap: 0.65rem;
    padding: 0.65rem 0.85rem;
  }

  .brand-section {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
  }

  .header-actions {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.4rem;
    flex-wrap: wrap;
  }

  .translation-toggle-group {
    flex: 1 1 auto;
    display: flex;
  }

  .btn-toggle-lang {
    flex: 1;
    text-align: center;
    padding: 0.4rem 0.5rem;
    font-size: 0.78rem;
    min-height: 38px;
  }

  .btn-toggle-parallel {
    padding: 0.4rem 0.65rem;
    font-size: 0.78rem;
    min-height: 38px;
  }

  .btn-icon {
    width: 38px;
    height: 38px;
  }

  /* View Navigation Tabs */
  .view-tabs-bar {
    padding-bottom: 0.4rem;
    -webkit-overflow-scrolling: touch;
  }

  .btn-view-tab {
    padding: 0.5rem 0.85rem;
    font-size: 0.82rem;
    min-height: 40px;
  }

  /* Passage Navigation Bar - Phone Thumb Friendly */
  .passage-nav-bar {
    flex-direction: column;
    align-items: stretch;
    gap: 0.75rem;
    padding: 0.85rem 0.75rem;
  }

  .nav-selectors-group {
    width: 100%;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.55rem;
  }

  .testament-pills {
    grid-column: 1 / -1;
    width: 100%;
    display: flex;
  }

  .btn-testament-pill {
    flex: 1;
    text-align: center;
    padding: 0.5rem 0.35rem;
    font-size: 0.78rem;
    min-height: 38px;
  }

  .custom-select {
    font-size: 16px !important; /* Prevents auto-zoom on iOS */
    min-height: 46px;
    padding: 0.55rem 1.75rem 0.55rem 0.75rem;
  }

  .book-select {
    grid-column: 1 / -1;
    width: 100%;
    min-width: 0;
  }

  .chapter-select,
  .verse-select {
    width: 100%;
    min-width: 0;
  }

  .nav-arrows-group {
    width: 100%;
    display: flex;
    gap: 0.5rem;
  }

  .btn-nav-arrow {
    flex: 1;
    justify-content: center;
    min-height: 44px;
    font-size: 0.88rem;
    padding: 0.55rem 0.75rem;
  }

  /* Daily Verse Card */
  .daily-verse-card {
    padding: 1.25rem 1rem;
    border-radius: var(--radius-md);
  }

  .daily-verse-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.65rem;
  }

  .daily-verse-actions {
    width: 100%;
    display: flex;
    gap: 0.5rem;
  }

  .btn-daily-action {
    flex: 1;
    justify-content: center;
    min-height: 42px;
    font-size: 0.82rem;
  }

  .daily-verse-quote {
    font-size: clamp(1.05rem, 3.8vw, 1.25rem);
    line-height: 1.75;
  }

  .daily-verse-telugu {
    font-size: clamp(1.1rem, 4vw, 1.35rem);
    line-height: 1.85;
  }

  /* Reader Card */
  .reader-card {
    padding: 1.25rem 0.85rem;
    min-height: auto;
    border-radius: var(--radius-md);
  }

  .chapter-header {
    margin-bottom: 1.25rem;
    padding-bottom: 0.85rem;
  }

  .chapter-heading {
    font-size: clamp(1.5rem, 5.5vw, 2rem);
  }

  .chapter-meta-badges {
    flex-wrap: wrap;
    gap: 0.35rem;
  }

  /* Verses Single Layout on Mobile */
  .verse-item {
    padding: 0.65rem 0.5rem;
    gap: 0.5rem;
  }

  .verse-number {
    font-size: 0.82rem;
    min-width: 28px;
  }

  .verse-text {
    font-size: clamp(1rem, 3vw, var(--bible-verse-font-size));
    line-height: 1.8;
  }

  /* Bottom Chapter Nav */
  .bottom-nav-mobile {
    gap: 0.5rem;
    padding: 0.75rem;
  }

  .bottom-nav-mobile .btn-nav-arrow {
    flex: 1;
    justify-content: center;
    min-height: 46px;
    font-size: 0.88rem;
  }

  /* Search Panel on Mobile */
  .search-controls-bar {
    flex-direction: column;
    gap: 0.65rem;
  }

  .search-input-wrapper {
    min-width: 0;
    width: 100%;
  }

  .search-input {
    font-size: 16px !important; /* Prevents auto-zoom on iOS */
    min-height: 46px;
  }

  .btn-search-submit {
    width: 100%;
    justify-content: center;
    min-height: 46px;
  }

  .search-options-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.65rem;
  }

  /* Bookmarks Panel on Mobile */
  .bookmarks-grid {
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .bookmark-card {
    padding: 1rem;
  }

  /* Offline Panel on Mobile */
  .offline-status-card {
    padding: 1.15rem;
  }

  .offline-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }

  .btn-offline-action {
    width: 100%;
    justify-content: center;
    min-height: 44px;
  }

  /* Toast on Mobile */
  .toast-container {
    left: 1rem;
    right: 1rem;
    bottom: 1.25rem;
    align-items: center;
  }

  .toast-message {
    width: 100%;
    text-align: center;
  }
}

/* --------------------------------------------------------------------------
   4. Extra-Small Phones (max-width: 420px)
   -------------------------------------------------------------------------- */
@media (max-width: 420px) {
  .brand-titles .brand-tagline {
    display: none;
  }

  .btn-toggle-parallel span:last-child {
    display: none; /* Shows only ⚖️ icon on tiny screens */
  }

  .btn-toggle-parallel {
    padding: 0.4rem 0.5rem;
  }

  .badge-translation,
  .badge-parallel,
  .badge-verse-count {
    font-size: 0.68rem;
    padding: 0.2rem 0.45rem;
  }
}

