// Home API Service: loads live backend endpoints with published filtering and graceful fallbacks
(function(root) {
  function getApiBaseUrl() {
    if (typeof window !== 'undefined' && window.API_BASE_URL) {
      return window.API_BASE_URL;
    }
    const host = typeof window !== 'undefined' ? window.location.hostname : '';
    const port = typeof window !== 'undefined' ? window.location.port : '';

    // Catalyst Slate cloud deployment -> AppSail backend
    if (host.includes('onslate.in')) {
      return 'https://church-app-60092968270.development.catalystappsail.in';
    }
    // Catalyst local development on port 3000
    if (port === '3000' || host === 'localhost') {
      return 'http://localhost:8000';
    }
    return '';
  }

  const BASE_URL = getApiBaseUrl();

  const homeApi = {
    // 1. Fetch Verse of the Day from live Bible API
    async fetchDailyVerse() {
      try {
        const res = await fetch(`${BASE_URL}/api/bible/daily-verse`, { cache: 'no-cache' });
        if (res.ok) {
          const data = await res.json();
          return {
            published: true,
            quote: data.text_kjv || "The Lord is my shepherd; I shall not want.",
            quoteTelugu: data.text_telugu || "",
            reference: `${data.book_name || 'Psalm'} ${data.chapter || 23}:${data.verse || 1} (KJV)`,
            referenceTelugu: `${data.book_name_telugu || 'కీర్తనలు'} ${data.chapter || 23}:${data.verse || 1}`,
            book: (data.book || 'psalms').toLowerCase(),
            chapter: data.chapter || 23,
            verse: data.verse || 1,
            image: "home/assets/open_bible_banner.jpg",
            buttonText: "Read in Bible",
            bibleLink: `bible/index.html?book=${encodeURIComponent((data.book || 'psalms').toLowerCase())}&chapter=${data.chapter || 23}`
          };
        }
      } catch (err) {
        console.warn('[HomeApi] /api/bible/daily-verse offline or unavailable, using fallback:', err.message);
      }
      // Fallback from mock data
      return (root.mockHomeData && root.mockHomeData.verseOfTheDay) || {
        published: true,
        quote: "The Lord is my shepherd; I shall not want.",
        reference: "Psalm 23:1 (KJV)",
        book: "psalms",
        chapter: 23,
        verse: 1,
        image: "home/assets/open_bible_banner.jpg",
        buttonText: "Read in Bible",
        bibleLink: "bible/index.html?book=psalms&chapter=23"
      };
    },

    // 2. Announcements
    async fetchAnnouncements() {
      try {
        const res = await fetch(`${BASE_URL}/api/announcements`);
        if (res.ok) {
          const json = await res.json();
          if (Array.isArray(json)) {
            return json.filter(item => item.published !== false);
          }
        }
      } catch (e) {
        // Fallback to published mock items
      }
      const items = (root.mockHomeData && root.mockHomeData.announcements) || [];
      return items.filter(item => item.published !== false);
    },

    // 3. Service Timings
    async fetchServiceTimings() {
      try {
